$:node <<'NODE'
"use strict";
const cp=require("node:child_process"),assert=require("node:assert/strict");
const file="workspaces/extractor-srs-design/VERIFICATION-PLAN.md";
const url="repos/BestNameYet/Terminals/contents/"+file;
function api(args){const x=cp.spawnSync("gh",["api",...args],{encoding:"utf8",maxBuffer:4*1024*1024});if(x.status!==0)throw Error((x.stderr||"").slice(0,650));return JSON.parse(x.stdout);}
const old="| EXT-AT-070 | EXT-FR-070 | Launch two concurrent exports to same branch | No lost updates; queued/serialized push operations | **NOT RUN** |";
const next="| EXT-AT-070 | EXT-FR-070 | Launch two concurrent exports to same branch | No lost updates; queued/serialized push operations | **PASS** — [independent 16-file verification](acceptance/results/E2E-008-distinct-41654917999-41654917547.json) |";
const src=api([url]);
const text=Buffer.from(src.content.replace(/\s/g,""),"base64").toString("utf8");
if(text.includes(next)){console.log(JSON.stringify({status:"ALREADY_RECORDED",file}));process.exit(0);}
assert.equal(text.split(old).length,2,"requirement status changed; refusing overwrite");
const updated=text.replace(old,next);
const write=api(["-X","PUT",url,"-f","message=Record EXT-AT-070 acceptance backed by independent E2E-008 report","-f","sha="+src.sha,"-f","content="+Buffer.from(updated).toString("base64")]);
const verify=api([url]);
assert.equal(Buffer.from(verify.content.replace(/\s/g,""),"base64").toString("utf8"),updated);
console.log(JSON.stringify({status:"PASS",commit:write.commit.sha,file,readback_verified:true,case_id:"EXT-AT-070",evidence:"acceptance/results/E2E-008-distinct-41654917999-41654917547.json"}));
NODE
